B.ayE=s(["Remover una vez en el horno: no se toca."],t.s)
B.aRA=s(["Caldo de cocido \u2192 caldo de pollo."],t.s)
B.b93=new A.a9(B.c8,B.aQM,"Horno a 220 \xb0C. Ten el caldo caliente.","No queda caldo, el arroz est\xe1 tierno y por arriba se ha dorado (unos 20 minutos de horno).",B.aqn,B.ayE,B.aRA,null,null,B.p)
B.ay0=s(["Olla","Sart\xe9n","Horno (opcional, para gratinar)"],t.s)
